export const traceKeys=['i0','i1','i2','i3','q','qB','pressureOK','fault'];
export function createTrace(capacity=3001){return {capacity,data:new Array(capacity),head:0,size:0,version:0};}
export function clearTrace(t){t.replaying=false;t.selected=null;t.head=0;t.size=0;t.version++;}
export function recordTrace(t,s){const last=t.size?t.data[(t.head+t.size-1)%t.capacity]:null;if(last&&s.time<last.time)clearTrace(t);const point={snapshot:traceSnapshot(s),pressure:s.pressure??4,time:s.time,A:s.x*100,B:s.y*100,state:s.state,cycle:s.cycles};for(const k of traceKeys)point[k]=Number(s[k]);if(t.size&&t.data[(t.head+t.size-1)%t.capacity].time===s.time){t.data[(t.head+t.size-1)%t.capacity]=point;}else if(t.size<t.capacity){t.data[(t.head+t.size++)%t.capacity]=point;}else{t.data[t.head]=point;t.head=(t.head+1)%t.capacity;}t.version++;return point;}
export function traceWindow(t,end,span){const start=Math.max(0,end-span),points=[];let previous=null;for(let i=0;i<t.size;i++){const p=t.data[(t.head+i)%t.capacity];if(p.time<start)previous=p;else points.push(p);}if(previous)points.unshift(previous);return {start,end:Math.max(span,end),points};}
export function stepPath(points,key,x,y){if(!points.length)return '';let d='M'+x(points[0].time)+','+y(points[0][key]);for(let i=1;i<points.length;i++)d+='H'+x(points[i].time)+'V'+y(points[i][key]);return d;}

// Store the evaluated scan, not a later reconstruction of ladder conditions.
export function traceSnapshot(s){const keys=['time','age','state','x','y','i0','i1','i2','i3','q','qB','pressure','pressureOK','fault','run','mode','manualA','manualB','cycles','target','complete','countPulse','delays','timers','scan','control','operatorMessage','alarms','events','disabledSensors','jamA','jamB','lowPressure'];return structuredClone(Object.fromEntries(keys.map(k=>[k,s[k]])));}
export function tracePoints(t){return Array.from({length:t.size},(_,i)=>t.data[(t.head+i)%t.capacity]);}
export function selectTrace(t,time){const points=tracePoints(t);t.selected=points.reduce((best,p)=>!best||Math.abs(p.time-time)<Math.abs(best.time-time)?p:best,null);return t.selected;}
export function moveTrace(t,direction,eventOnly=false){const points=tracePoints(t);let i=t.selected?points.indexOf(t.selected):points.length-1;if(i<0)i=points.length-1;for(let j=i+direction;j>=0&&j<points.length;j+=direction){if(!eventOnly||(j>0&&traceKeys.some(k=>points[j][k]!==points[j-1][k]))){t.selected=points[j];return t.selected;}}return t.selected||points[i];}
export function startReplay(t){const points=tracePoints(t);if(points.length<2)return false;if(!t.selected||t.selected===points.at(-1))t.selected=points[0];t.replayTime=t.selected.time;t.replaying=true;return true;}
export function advanceReplay(t,dt){if(!t.replaying||!t.selected)return;const points=tracePoints(t),end=points.at(-1);t.replayTime=Math.min(end.time,t.replayTime+Math.max(0,dt)*(t.replaySpeed||.25));let selected=points[0];for(const p of points){if(p.time>t.replayTime+1e-9)break;selected=p;}t.selected=selected;if(t.replayTime>=end.time-1e-9){t.selected=end;t.replaying=false;}}
